final class TapTestUITests: XCTestCase {
    func testOpenFirstPostAuthorProfile() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        _ = addUIInterruptionMonitor(withDescription: "Open in Bluesky") { alert in
            let open = alert.buttons["Open"]
            if open.exists {
                open.tap()
                return true
            }
            return false
        }
        app.launch()
        let name = app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "whiskers")).firstMatch
        XCTAssertTrue(name.waitForExistence(timeout: 20), "author not found")
        let f = name.frame
        let target = CGPoint(x: f.minX + 60, y: f.minY + 10)
        let coord = XCUICoordinate(element: app, normalizedOffset: CGVector(dx: target.x / app.frame.width, dy: target.y / app.frame.height))
        coord.tap()
        Thread.sleep(forTimeInterval: 5)
    }
}
